// Install a ported constructor: BIOSYS_REGISTER_CTOR(1000ec80, [](World& w, const char* name, ...) -> Item* { ... });
#define BIOSYS_REGISTER_CTOR(addr, ...) \
    static const ::biosys::game::CtorRegistrar<::biosys::game::CtorFn_##addr> biosysReg_##addr(::biosys::game::ctorSlot_##addr(), __VA_ARGS__)

template <class Fn> struct CtorRegistrar {
    CtorRegistrar(Fn& slot, Fn fn) { slot = fn; }
};

struct CtorInfo {
    uint32_t addr;
    const char* ctorName;     // name in the decompilation
    const char* className;    // class in the save format (analysis/notes/saveblob.md)
    const char* lists;        // world list(s) the constructed items end up in
    int calls;                // calls in the replayed world build
    const char* signature;    // s string, i/u/h int32/uint32/uint16, d/D double, r item, c site cel, b biome, g DLL pointer
};
const std::vector<CtorInfo>& allCtors();

